/** routes.json is generated by scripts/twin/build-campus-data.mjs; the tours must match it. */
interface RoutesFile {
  walkSpeed: number;
  legs: Record<string, { lengthM: number; points: [number, number, number][] }>;
  tours: { id: string; legs: string[]; to: string; distanceM: number; minutes: number }[];
}
const routes = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), "public/assets/guide/3d/data/routes.json"), "utf8"),
) as RoutesFile;

const PLACE_IDS: PlaceId[] = ["campus", "educity", "biocity", "joki"];
const unique = (xs: readonly string[]) => new Set(xs).size === xs.length;

/* ── Route geometry (campus frame: metres, +x east, +z south, so north is −z) ── */

const DEG = 180 / Math.PI;
/** Compass bearing (0 = north, 90 = east) of a ground direction. */
const bearing = (dx: number, dz: number) => ((Math.atan2(dx, -dz) * DEG) % 360 + 360) % 360;
/** Signed change of heading from bearing a to bearing b, −180…180: negative = a left turn. */
const headingChange = (a: number, b: number) => ((b - a + 540) % 360) - 180;

/** A tour's path from routes.json, with where each step's anchor lies along it (in walking order). */
function tourWalk(t: twin.Tour3D) {
  const path = t.legs.flatMap((id) => routes.legs[id].points.map(([x, , z]) => [x, z] as [number, number]));
  const cum = [0];
  for (let i = 1; i < path.length; i++)
    cum.push(cum[i - 1] + Math.hypot(path[i][0] - path[i - 1][0], path[i][1] - path[i - 1][1]));
  const total = cum[cum.length - 1];
  /** The point `s` metres along the path. */
  const at = (s: number): [number, number] => {
    const d = Math.max(0, Math.min(total, s));
    const i = Math.max(1, cum.findIndex((c) => c >= d));
    const u = (d - cum[i - 1]) / (cum[i] - cum[i - 1] || 1);
    return [path[i - 1][0] + u * (path[i][0] - path[i - 1][0]), path[i - 1][1] + u * (path[i][1] - path[i - 1][1])];
  };
  /** Heading of the straight line from s0 to s1 metres along — smooths out the router's sub-metre jogs. */
  const heading = (s0: number, s1: number) => {
    const [ax, az] = at(s0);
    const [bx, bz] = at(s1);
    return bearing(bx - ax, bz - az);
  };
  // Each anchor: the nearest point on the path at or after the previous step's.
  const anchors: { along: number; d: number }[] = [];
  let from = 0;
  for (const s of t.steps) {
    const [ax, az] = s.at ?? [Infinity, Infinity];
    let best = { d: Infinity, along: 0 };
    for (let i = 1; i < path.length; i++) {
      const [px, pz] = path[i - 1];
      const [qx, qz] = path[i];
      const l2 = (qx - px) ** 2 + (qz - pz) ** 2 || 1;
      const u = Math.max(0, Math.min(1, ((ax - px) * (qx - px) + (az - pz) * (qz - pz)) / l2));
      const along = cum[i - 1] + u * Math.sqrt(l2);
      if (along < from - 0.5) continue;
      const d = Math.hypot(ax - (px + u * (qx - px)), az - (pz + u * (qz - pz)));
      if (d < best.d - 1e-9) best = { d, along };
    }
    anchors.push(best);
    from = best.along;
  }
  return { total, at, heading, anchors };
}

/**
 * The turns of more than 45° between s0 and s1 metres along the path, in order: −1 = left,
 * +1 = right. Each 3 m stretch is compared with the heading before the turn.
 */
function turnsAlong(w: ReturnType<typeof tourWalk>, s0: number, s1: number): number[] {
  const turns: number[] = [];
  const end = Math.min(s1, w.total - 3);
  let ref = w.heading(s0, s0 + 3);
  for (let s = s0; s <= end; s += 0.5) {
    const change = headingChange(ref, w.heading(s, s + 3));
    if (Math.abs(change) > 45) {
      turns.push(Math.sign(change));
      s += 3; // past the corner
      ref = w.heading(s, s + 3);
    }
  }
  return turns;
}

describe("places", () => {
  it("are campus, EduCity, BioCity and Joki, each with a default view first", () => {
    expect(PLACES_3D.map((p) => p.id)).toEqual(PLACE_IDS);
    for (const p of PLACES_3D) {
      expect(p.views[0].id).toBe("default");
      expect(unique(p.views.map((v) => v.id))).toBe(true);
      expect(p.views.length).toBeGreaterThanOrEqual(4);
      for (const field of [p.tab, p.title, p.caption, p.alt, p.poster]) expect(field.trim()).not.toBe("");
      expect(p.poster).toMatch(/^\/assets\/guide\/3d\/.+\.webp$/);
      expect(getPlace3D(p.id)).toBe(p);
    }
  });

  it("offer the agreed views", () => {
    const views = Object.fromEntries(PLACES_3D.map((p) => [p.id, p.views.map((v) => `${v.id}:${v.label}`)]));
    expect(views).toEqual({
      campus: ["default:Overview", "arrival:Arrival · Tykistökatu", "courtyard:Jussin aukio", "top:Plan view"],
      educity: [
        "default:Lobby & Taidon portaat",
        "rooms1:Floor 1 rooms",
        "rooms2:Floor 2 rooms",
        "entrance:Main entrances",
      ],
      biocity: [
        "default:Build hall",
        "entrance:Partner entrance · Tykistökatu",
        "gallery:Aulagalleria",
        "stands:Partner stands",
      ],
      joki: ["default:Aula & Cave", "showroom:Showroom", "lounge:Company Lounge", "floors:Floors 2–3"],
    });
  });

  it("throw on an unknown place", () => {
    expect(() => getPlace3D("moon" as PlaceId)).toThrow("Unknown 3D place");
    expect(isPlaceId("joki")).toBe(true);
    expect(isPlaceId("lounge")).toBe(false);
    expect(isPlaceId(null)).toBe(false);
  });
});

