describe("tours", () => {
  it("have unique ids, real steps and end at a known target in their place", () => {
    expect(unique(TOURS_3D.map((t) => t.id))).toBe(true);
    for (const t of TOURS_3D) {
      expect(getTarget3D(t.to)).toBeDefined();
      expect(t.place).toBe(placeForTarget(t.to));
      expect(t.steps.length).toBeGreaterThanOrEqual(3);
      for (const s of t.steps) expect(s.text).toMatch(/^[A-Z].*[.)]$/);
      expect(getTour3D(t.id)).toBe(t);
    }
  });

  it("use legs that exist in routes.json, connected end to end", () => {
    for (const t of TOURS_3D) {
      for (const id of t.legs) expect(routes.legs[id]).toBeDefined();
      for (let i = 1; i < t.legs.length; i++) {
        const a = routes.legs[t.legs[i - 1]].points.at(-1)!;
        const b = routes.legs[t.legs[i]].points[0];
        expect(Math.hypot(a[0] - b[0], a[2] - b[2])).toBeLessThan(0.6);
      }
    }
  });

  it("quote the measured distances and times (sum of the legs at 1.3 m/s)", () => {
    for (const t of TOURS_3D) {
      const sum = t.legs.reduce((n, id) => n + routes.legs[id].lengthM, 0);
      expect(Math.abs(t.distanceM - sum)).toBeLessThanOrEqual(1);
      expect(t.minutes).toBeCloseTo(t.distanceM / routes.walkSpeed / 60, 1);
    }
  });

  it("anchor every step on its route, in walking order", () => {
    for (const t of TOURS_3D) {
      for (const s of t.steps) expect(s.at).toBeDefined();
      const { anchors } = tourWalk(t);
      // Nearest point on the path at or after the previous step.
      for (const a of anchors) expect(a.d).toBeLessThan(3);
    }
  });

  it("number their steps uniquely (the 3D shows and announces the step a caption belongs to)", () => {
    for (const t of TOURS_3D) expect(unique(t.steps.map((s) => s.text))).toBe(true);
  });

  it("say left and right the way the route really turns", () => {
    // "<landmark> on your left/right": where the landmark stands ([x, z], LANDMARKS in engine/frame.ts).
    const SIDE_LANDMARKS: Record<string, [number, number]> = { "Joki tower": [58.9, 15.9] };
    const checked: string[] = [];
    for (const t of TOURS_3D) {
      const w = tourWalk(t);
      t.steps.forEach((step, i) => {
        const from = w.anchors[i].along;
        const until = i + 1 < t.steps.length ? w.anchors[i + 1].along : w.total;
        const turnWords: number[] = [];
        for (const clause of step.text.split(/[,;.—]/)) {
          for (const m of clause.matchAll(/\b(left|right)\b/gi)) {
            const side = m[1].toLowerCase() === "left" ? -1 : 1;
            const landmark = Object.keys(SIDE_LANDMARKS).find((name) => clause.includes(name));
            if (landmark && /\bon your (left|right)\b/i.test(clause)) {
              // A side: the landmark is on that side of the path where the step passes closest to it.
              const [lx, lz] = SIDE_LANDMARKS[landmark];
              let s = from;
              for (let x = from; x <= until; x += 0.5) {
                const [px, pz] = w.at(x);
                const [bx, bz] = w.at(s);
                if (Math.hypot(lx - px, lz - pz) < Math.hypot(lx - bx, lz - bz)) s = x;
              }
              const h = w.heading(Math.max(0, s - 1.5), Math.min(w.total, s + 1.5)) / DEG;
              const [dx, dz] = [Math.sin(h), -Math.cos(h)];
              const [px, pz] = w.at(s);
              // Right of the walking direction (dx, dz) is (−dz, dx) in this frame.
              const right = (lx - px) * -dz + (lz - pz) * dx;
              expect({ tour: t.id, step: i + 1, text: step.text, side: Math.sign(right) }).toEqual({
                tour: t.id,
                step: i + 1,
                text: step.text,
                side,
              });
            } else {
              turnWords.push(side);
            }
            checked.push(`${t.id}#${i + 1}`);
          }
        }
        if (!turnWords.length) return;
        // A turn: the first turns from the step's anchor on (from a little before it — corners are rounded,
        // so a turn can start a few metres before its anchor, never before the previous step's).
        const prev = i > 0 ? w.anchors[i - 1].along : 0;
        const turns = turnsAlong(w, Math.max(prev, from - 12), until + 3);
        expect({ tour: t.id, step: i + 1, text: step.text, turns: turns.slice(0, turnWords.length) }).toEqual({
          tour: t.id,
          step: i + 1,
          text: step.text,
          turns: turnWords,
        });
      });
    }
    // The check really ran: every left/right in the routes, including the ParkCity → BioCity start.
    expect(checked).toContain("companies-parkcity-to-biocity#1");
    expect(checked).toContain("builders-transfer-to-build#4");
    expect(checked.length).toBeGreaterThanOrEqual(12);
  });

  it("match the tours in routes.json", () => {
    expect(routes.tours.map((t) => t.id)).toEqual(TOURS_3D.map((t) => t.id));
    for (const t of TOURS_3D) {
      const r = routes.tours.find((x) => x.id === t.id)!;
      expect(r.legs).toEqual(t.legs);
      expect(r.to).toBe(t.to);
      expect(r.distanceM).toBe(t.distanceM);
      expect(r.minutes).toBe(t.minutes);
    }
  });

  it("cover the arrivals and moves of the weekend", () => {
    const to = (id: string) => getTour3D(id)!.to;
    expect(to("builders-train-checkin")).toBe("registration");
    expect(to("partners-fri-parkcity-edu")).toBe("company-arrival");
    expect(to("partners-fri-train-edu")).toBe("company-arrival");
    expect(to("partners-tykistokatu-to-stands")).toBe("bc-1");
    expect(to("builders-transfer-to-build")).toBe("build-hall");
    expect(to("companies-tykistokatu-to-showroom")).toBe("showroom");
    expect(to("builders-build-to-joki")).toBe("showroom");
    expect(to("builders-back-to-educity")).toBe("taidon-portaat");
    expect(TOURS_3D.length).toBe(12);
  });

  it("agree with the guide on the EduCity → BioCity transfer (about 200 m outdoors, 3 min)", () => {
    const xfer = getTour3D("builders-transfer-to-build")!;
    const outdoor = routes.legs[xfer.legs[0]].lengthM;
    expect(outdoor).toBeGreaterThan(190);
    expect(outdoor).toBeLessThan(220);
    expect(Math.round(outdoor / routes.walkSpeed / 60)).toBe(3);
    expect(TRANSFER_ROUTE.approxOutdoorDistance).toMatch(/200 m/);
    expect(getPlace3D("campus").caption).toMatch(/about 200 m/);
  });
});

describe("company routes", () => {
  const FRI = ["partners-fri-parkcity-edu", "partners-fri-train-edu", "partners-fri-stepfree-edu"];
  const SAT = ["companies-tykistokatu-to-showroom", "companies-train-to-biocity", "companies-parkcity-to-biocity"];
  const roomNumbers = (c: (typeof CHALLENGE_COMPANIES)[number]) => c.briefing.room.split(/\s*\/\s*/);

  it("name no single company's room in the routes everyone sees", () => {
    for (const t of TOURS_3D) {
      for (const text of [t.summary, ...t.steps.map((s) => s.text)]) expect(text).not.toMatch(/\broom \d{4}\b/);
    }
    for (const id of ["company-arrival", "entrance-educity-b"]) {
      expect(getTarget3D(id)!.label).not.toMatch(/\d{4}/);
      expect(getTarget3D(id)!.detail).not.toMatch(/\d{4}/);
    }
  });

  it("lead each company to its own Friday room and Saturday stand, keeping the steps' anchors", () => {
    for (const c of CHALLENGE_COMPANIES) {
      for (const id of [...FRI, ...SAT]) {
        const base = getTour3D(id)!;
        const t = twin.tourForCompany(base, c.id)!;
        expect(t.id).toBe(base.id);
        expect(t.steps.map((s) => s.at)).toEqual(base.steps.map((s) => s.at));
        expect(t.steps.slice(0, -1)).toEqual(base.steps.slice(0, -1));
        const text = `${t.summary} ${t.steps.at(-1)!.text}`;
        expect(t.steps.at(-1)!.text).toMatch(/^[A-Z].*[.)]$/);
        if (FRI.includes(id)) {
          expect(t.arrival).toBe(`room-${c.id}`);
          expect(text).toContain(`room ${briefingRoomLabel(c)}`);
          expect(text).toContain(`floor ${c.briefing.floor}`);
          for (const o of CHALLENGE_COMPANIES.filter((x) => x.briefing.room !== c.briefing.room))
            for (const n of roomNumbers(o)) expect(text).not.toContain(n);
        } else {
          expect(t.arrival).toBe(c.id);
          const counter = showroomCounter(c);
          expect(text).toContain(counter ? `counter ${counter} of ${SHOWROOM_ORDER.length}` : `floor ${c.qa.floor}`);
          // Saturday: the stand is ready — the Since AI team set it up from what the partner brought on Friday.
          expect(t.steps.at(-1)!.text).toMatch(/ready, set up by the Since AI team from the materials you brought on Friday/);
        }
      }
    }
  });

  it("leave other routes and unknown companies alone", () => {
    expect(twin.tourForCompany(getTour3D("builders-train-checkin")!, "elisa")).toBeNull();
    expect(twin.tourForCompany(getTour3D(FRI[0])!, "nope")).toBeNull();
    expect(twin.tourForCompany(getTour3D(FRI[0])!, null)).toBeNull();
  });

  it("give every step a short place name for the route card's now / next", () => {
    for (const t of TOURS_3D) for (const s of t.steps) expect(s.where?.trim()).toBeTruthy();
  });

  it("pair each company's Q&A stand with its Friday room and point at their floor plans", () => {
    for (const c of CHALLENGE_COMPANIES) {
      const stand = getTarget3D(c.id)!;
      const room = getTarget3D(`room-${c.id}`)!;
      expect(stand).toMatchObject({ company: c.id, day: "Sat", map: c.qa.floor === 1 ? "joki-showroom" : "joki-2-3" });
      expect(room).toMatchObject({ company: c.id, day: "Fri", map: c.briefing.floor === 1 ? "educity-1" : "educity-2" });
      expect(room.where).toBe(`EduCity · room ${c.briefing.room}`);
    }
    for (const t of TARGETS_3D) if (t.href?.includes("#map-")) expect(t.href).toBe(twin.mapHref(t.map!));
  });
});

describe("time presets", () => {
  it("are valid Turku wall-clock times during the event weekend", () => {
    expect(unique(TIME_PRESETS.map((p) => p.id))).toBe(true);
    const start = EVENT_2026.window.start.slice(0, 16);
    const end = EVENT_2026.window.end.slice(0, 16);
    for (const p of TIME_PRESETS) {
      expect(p.iso).toMatch(/^2026-11-0[6-8]T([01]\d|2[0-3]):[0-5]\d$/);
      const d = new Date(`${p.iso}:00Z`);
      expect(Number.isNaN(d.getTime())).toBe(false);
      expect(p.iso >= start && p.iso <= end).toBe(true);
      expect(p.label).toContain(p.iso.slice(11, 16));
    }
  });

  it("are the agreed moments, starting with Friday's arrival", () => {
    expect(TIME_PRESETS.map((p) => [p.id, p.iso])).toEqual([
      ["arrival", "2026-11-06T15:30"],
      ["sunset", "2026-11-06T16:20"],
      ["opening", "2026-11-06T17:00"],
      ["night", "2026-11-07T01:00"],
      ["qa", "2026-11-07T11:00"],
      ["closing", "2026-11-08T13:30"],
    ]);
    expect(DEFAULT_TIME).toBe("2026-11-06T15:30");
  });
});

describe("deep links", () => {
  it("normalise partners to their stands and ignore case", () => {
    expect(normaliseTarget("red-hat")).toBe("bc-1");
    expect(normaliseTarget("solita")).toBe("bc-2");
    expect(normaliseTarget("Red-Hat")).toBe("bc-1");
    expect(normaliseTarget(" ELISA ")).toBe("elisa");
    expect(normaliseTarget("BC-3")).toBe("bc-3");
  });

  it("map room numbers to the company's room and drop unknown ids", () => {
    expect(normaliseTarget("room-1002")).toBe("room-bayer");
    expect(normaliseTarget("room-2006")).toBe("room-valmet");
    expect(normaliseTarget("room-bayer")).toBe("room-bayer");
    expect(normaliseTarget("room-9999")).toBeNull();
    expect(normaliseTarget("nope")).toBeNull();
    expect(normaliseTarget("biocity")).toBeNull();
    expect(normaliseTarget("")).toBeNull();
    expect(normaliseTarget(null)).toBeNull();
    expect(normaliseTarget(undefined)).toBeNull();
  });

  it("place targets: companies in Joki, rooms in EduCity, stands in BioCity", () => {
    for (const c of CHALLENGE_COMPANIES) expect(placeForTarget(c.id)).toBe("joki");
    expect(placeForTarget("room-elisa")).toBe("educity");
    expect(placeForTarget("room-1001")).toBe("educity");
    expect(placeForTarget("bc-4")).toBe("biocity");
    expect(placeForTarget("red-hat")).toBe("biocity");
    expect(placeForTarget("solita")).toBe("biocity");
    expect(placeForTarget("entrance-joki-street")).toBe("joki");
    expect(placeForTarget("entrance-educity-something")).toBe("educity");
    expect(placeForTarget("lounge")).toBe("joki");
    expect(placeForTarget("registration")).toBe("educity");
    expect(placeForTarget("supercars")).toBe("biocity");
    expect(placeForTarget("jussin-aukio")).toBe("campus");
    expect(placeForTarget("joki")).toBe("joki");
    expect(placeForTarget("unknown")).toBe("campus");
    expect(placeForTarget(null)).toBe("campus");
  });

  it("understand the previous preview's ?scene= values", () => {
    expect(legacyScene("showroom")).toEqual({ place: "joki", view: "showroom" });
    expect(legacyScene("joki-tower")).toEqual({ place: "joki", view: "floors" });
    expect(legacyScene("biocity")).toEqual({ place: "biocity", view: "default" });
    expect(legacyScene("BioCity")).toEqual({ place: "biocity", view: "default" });
    expect(legacyScene("nope")).toBeNull();
    expect(legacyScene(null)).toBeNull();
    for (const ref of ["showroom", "joki-tower", "biocity"]) {
      const { place, view } = legacyScene(ref)!;
      expect(getPlace3D(place).views.map((v) => v.id)).toContain(view);
    }
  });

  it("export the twin's normaliseTarget from the package index", () => {
    expect(normaliseTarget).toBe(twin.normaliseTarget);
  });
});

describe("copy", () => {
  const corpus = JSON.stringify({ PLACES_3D, TARGETS_3D, TOURS_3D, TIME_PRESETS });

  it("uses the corrected venue facts (SPEC §10)", () => {
    expect(corpus).not.toMatch(/(?<!\d)50 m/); // the old "approx. 50 m outdoors" claim
    expect(corpus).not.toMatch(/first floor/i);
    expect(corpus).not.toMatch(/ground-floor main entrance/i);
    expect(corpus).toMatch(/Joki street door/);
    const joki = VENUES.find((v) => v.id === "joki")!;
    expect(joki.entrances.find((e) => e.label === "Street door")?.detail).toMatch(/closed during the event/);
  });

  it("names the companies and stands from the shared data", () => {
    for (const c of CHALLENGE_COMPANIES) expect(corpus).toContain(c.name);
    expect(getPlace3D("joki").alt).toContain("Meyer Turku, DNA, Apetit, Elisa, Turku Energia and Bayer");
    expect(getPlace3D("biocity").alt).toContain("Red Hat's stand (Stand 1)");
  });

  it("credits the open data", () => {
    expect(TWIN_CREDITS).toMatch(/© Turun kaupunki, CC BY 4\.0/);
    expect(TWIN_CREDITS).toMatch(/OpenStreetMap contributors/);
  });
});
